_PER_USD = {
    "EGP": (("2018-01", 31.0), ("2024-03", 48.0)),
    "VND": (("2018-01", 25_000.0),),
}


def _month(ts: datetime) -> str:
    return f"{ts.year:04d}-{ts.month:02d}"


def rate(code: str, ts: datetime) -> float | None:
    """
    Курс валюты на месяц момента: ближайший известный месяц не позже
    (до таблицы — первый, после — последний).
    """

    if code in _PER_USD:
        usd = rate("USD", ts)
        steps = _PER_USD[code]
        per = steps[0][1]
        for since, value in steps:
            if _month(ts) >= since:
                per = value
        return usd / per if usd else None

    table = FX_MONTHLY.get(code)

    if not table:
        return None

    key = _month(ts)

    known = sorted(table)

    if key <= known[0]:
        return table[known[0]]

    if key >= known[-1]:
        return table[known[-1]]

    return table[max(item for item in known if item <= key)]
